INSERT INTO `cot_insumos` (`IDTIPOINSUMO`, `NOMBREINSUMO`, `DESCRIPCIONINS`, `PRECIO8H`, `PRECIO4H`, `PRECIOUNITARIO`, `PRECIOVENTA`, `FECHAREGINS`, `USUREGINS`, `FECHAMODINS`, `USUMODINS`) VALUES 
('2', 'Sin Alimentación', 'Sin Alimentación', NULL, NULL, NULL, '0.0', '2025-09-09 15:08:26', 'AMolina', NULL, NULL), 
('2', 'Refrigerio sencillo', '1 pieza de refrigerio salada o dulce con peso mínimo de 4 onzas; incluye café, té, agua, refresco natural o soda. ', NULL, NULL, NULL, '8.76', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Refrigerio doble', '2 piezas de refrigerios salados y/o dulces con peso mínimo de 4 onzas cada una; incluye café, té, agua, refresco natural o soda.', NULL, NULL, NULL, '9.61', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Jornada completa sin postre', '2 piezas de refrigerios (matutino y vespertino) con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos.', NULL, NULL, NULL, '23.17', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Jornada completa con postre', '2 piezas de refrigerios (matutino y vespertino) con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos + Postre.', NULL, NULL, NULL, '24.30', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Jornada completa con refrigerio doble am y pm con postre', '4 piezas de refrigerios (2 matutino y 2 vespertino) con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos + Postre.', NULL, NULL, NULL, '31.64', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Jornada completa con refrigerio doble am y sencillo pm C/Postre', '3 piezas de refrigerios (2 matutino y 1 vespertino) con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos.', NULL, NULL, NULL, '25.59', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Media jornada', '1 piezas de refrigerios dulce o salado con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos.', NULL, NULL, NULL, '18.36', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Media jornada + Postre', '1 piezas de refrigerios dulce o salado con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos.', NULL, NULL, NULL, '20.28', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Media jornada + ref. doble', '2 piezas de refrigerios dulce o salado con peso mínimo de 4 onzas cada uno; y 1 almuerzo que incluya ensalada (peso mínimo 3 onzas), guarnición (peso mínimo 4 onzas), plato fuerte (peso mínimo 4 onzas) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda en todos los tiempos.', NULL, NULL, NULL, '22.60', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Desayunos', 'Ejemplo: -4 onz de frijoles frito, 4 onz de huevo frito o revuelto, 4 onz de plátano, 2onz de queso o crema, 2 bollos de pan incluye café ó té y jugo natural. -4 onz de frijoles fritos, 1 tamal de 4onz minimo, 2 onz de queso o crema, 2 bollos de pan, incluye café o té y jugo natrual. -2 pancakes con fruta y miel de abeja o maple, incluye café o té y jugo natural.', NULL, NULL, NULL, '12.43', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'almuerzo o cena económica', 'Incluye ensalada (peso minimo 3 onz), guarnición (peso mínimo 4onz), plato fuerte (peso mínimo 4 onz) y 2 bollo de pan francés o tortilla; incluye café, té, agua, refresco natural o soda.', NULL, NULL, NULL, '16.39', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'almuerzo o cena económica con postre', 'Incluye ensalada (peso minimo 3 onz), guarnición (peso mínimo 4onz), plato fuerte (peso mínimo 4 onz) y 2 bollo de pan francés o tortilla; incluye café, té, agua, refresco natural o soda.', NULL, NULL, NULL, '16.95', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Almuerzo o cena premium con postre', 'Incluye ensalada (peso mínimo 3 onzas), 2 guarniciones (peso mínimo 3 onzas cada una), 2 porciones de proteína (peso mínimo 3 onzas cada una) y 2 bollos de pan francés o 2 tortillas; incluye café, té, agua, refresco natural o soda.', NULL, NULL, NULL, '22.88', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Almuerzos Ligeros', 'Hambuerguesas, Hot Dog, Panini, Pizza, Pan con pollo acompañado con papas fritas, soda lata y resposteria.', NULL, NULL, NULL, '15.50', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Platos de bocas', 'bocas.', NULL, NULL, NULL, '2.73', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Platos de bocas', 'servicio de bar, hielo.', NULL, NULL, NULL, '1.19', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Platos de bocas', 'servicio de bar con bebida soda o refresco.', NULL, NULL, NULL, '1.98', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Servicio de uso de copa de vino', 'Cristaleria para vino tinto o blanco.', NULL, NULL, NULL, '1.13', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
('2', 'Mesas cócteleras', 'Adicionales vestidas.', NULL, NULL, NULL, '13.56', '2025-09-09 15:08:26', 'AMolina', NULL, NULL),
